public class BreakpointHitReporterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void finish() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    public static void main(String[] args) {
        BreakpointHitReporter reporter = new BreakpointHitReporter();
        check("report with nothing registered", "", reporter.report());
        check("neverHit with nothing registered", "[]", String.valueOf(reporter.neverHit()));

        reporter.addBreakpoint(20);
        reporter.addBreakpoint(12);
        reporter.addBreakpoint(33);
        int[] executed = {5, 12, 20, 12, 41, 12};
        for (int line : executed) {
            reporter.execute(line);
        }
        reporter.addBreakpoint(12);

        check("hits on a busy breakpoint", 3, reporter.hits(12));
        check("hits on a breakpoint hit once", 1, reporter.hits(20));
        check("hits on a cold breakpoint", 0, reporter.hits(33));
        check("hits on a line with no breakpoint", 0, reporter.hits(41));
        check("re-registering did not reset the count", 3, reporter.hits(12));
        check("neverHit", "[33]", String.valueOf(reporter.neverHit()));
        check("report is ordered by line number",
                "line 12: 3 hit(s)\nline 20: 1 hit(s)\nline 33: 0 hit(s)", reporter.report());
        finish();
    }
}

