public class BreakpointHitReporter {

    private final java.util.Map<Integer, Integer> counts = new java.util.TreeMap<>();

    public void addBreakpoint(int line) {
        if (!counts.containsKey(line)) {
            counts.put(line, 0);
        }
    }

    public void execute(int line) {
        if (counts.containsKey(line)) {
            counts.put(line, counts.get(line) + 1);
        }
    }

    public int hits(int line) {
        if (!counts.containsKey(line)) {
            return 0;
        }
        return counts.get(line);
    }

    public java.util.List<Integer> neverHit() {
        java.util.List<Integer> result = new java.util.ArrayList<>();
        for (java.util.Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            if (entry.getValue() == 0) {
                result.add(entry.getKey());
            }
        }
        return result;
    }

    public String report() {
        StringBuilder out = new StringBuilder();
        for (java.util.Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            if (out.length() > 0) {
                out.append("\n");
            }
            out.append("line ").append(entry.getKey())
               .append(": ").append(entry.getValue()).append(" hit(s)");
        }
        return out.toString();
    }
}
